Describe 'EXP-156 shopping assistant lab harness contract' {
 BeforeAll {$sut=Join-Path $PSScriptRoot 'Invoke-Exp156LabHarness.ps1';$script:text=Get-Content -LiteralPath $sut -Raw}
 It 'defaults to five matched runs and 120-second sampling' {$script:text|Should -Match "RunsPerArm=5";$script:text|Should -Match "SampleSeconds=120"}
 It 'requires the controlled profile fixture and current provider' {$script:text|Should -Match 'ProfileFixturePath';$script:text|Should -Match 'EdgeDisableShoppingAssistant.ps1';$script:text|Should -Match '-ProfileFixturePath \$ProfileFixturePath'}
 It 'uses provider support detection before physical evidence setup' {$script:text|Should -Match "Provider 'Check'";$script:text|Should -Match '\$check\.Support\.Supported';$script:text|Should -Match "Provider 'Capture'.*Provider 'DryRun'.*WriteJson.*Harness"}
 It 'supports baseline treatment reboot continuation and duplicate-boot refusal' {$script:text|Should -Match "phase='Baseline'";$script:text|Should -Match "phase='Treatment'";$script:text|Should -Match 'Duplicate collection from same boot refused';$script:text|Should -Match "Provider 'VerifyReboot'"}
 It 'delegates the single policy treatment and exact restore to the provider' {$script:text|Should -Match "Provider 'Apply'";$script:text|Should -Match "Provider 'Verify'";$script:text|Should -Match "Provider 'Rollback'";$script:text|Should -Not -Match 'New-ItemProperty'}
 It 'retains structured evidence and matched-run dispersion' {$script:text|Should -Match 'lab-events\.jsonl';$script:text|Should -Match 'run-\{0\}-\{1:D2\}\.json';$script:text|Should -Match 'function Median';$script:text|Should -Match 'function Mad';$script:text|Should -Match 'cpuMedianPercent';$script:text|Should -Match 'diskMedianBytesPerSec'}
 It 'captures Edge and protected-scope observations' {$script:text|Should -Match 'Get-Process msedge';$script:text|Should -Match 'WinDefend';$script:text|Should -Match 'mpssvc';$script:text|Should -Match 'wuauserv';$script:text|Should -Match 'edgeupdate';$script:text|Should -Match 'TermService';$script:text|Should -Match 'Tailscale';$script:text|Should -Match 'windowsapp';$script:text|Should -Match 'omnissa'}
 It 'preserves unresolved physical shopping and navigation evidence explicitly' {$script:text|Should -Match 'shoppingRequestAttribution';$script:text|Should -Match 'networkBytes';$script:text|Should -Match 'retailFixtureNavigation';$script:text|Should -Match 'shoppingAssistantEligibilityOrAbsence';$script:text|Should -Match 'autofillAndPaymentsRegression';$script:text|Should -Match 'controlledNavigationReadiness';$script:text|Should -Match 'needs-evidence'}
 It 'requires explicit automatic reboot authorization and carries it into continuation' {$script:text|Should -Match 'AllowAutomaticReboot';$script:text|Should -Match 'reboot-required';$script:text|Should -Match "if\(\$AllowAutomaticReboot\)\{\$arg\+=' -AllowAutomaticReboot'\}"}
 It 'uses a reversible current-user continuation task only for reboot sequencing' {$script:text|Should -Match 'New-ScheduledTaskTrigger -AtLogOn';$script:text|Should -Match 'Register-ScheduledTask';$script:text|Should -Match 'Unregister-ScheduledTask';$script:text|Should -Match 'Provider ''Rollback'''}
 It 'keeps production policy mutation outside the harness' {$script:text|Should -Not -Match 'Set-ItemProperty';$script:text|Should -Not -Match 'Remove-ItemProperty';$script:text|Should -Not -Match 'reg\.exe';$script:text|Should -Not -Match 'Set-Service'}
}
